use crate::wasi::clocks::wall_clock;

struct Node;

/// Converts days since 1970-01-01 to (year, month, day).
/// Howard Hinnant's `civil_from_days` algorithm, proleptic Gregorian calendar.
fn civil_from_days(z: i64) -> (i64, i64, i64) {
    let z = z + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

/// Formats a unix timestamp in seconds as `YYYY-MM-DD` (always 10 characters).
fn format_date(seconds: u64) -> String {
    let days = (seconds / 86_400) as i64;
    let (y, m, d) = civil_from_days(days);
    if y < 0 {
        return "0000-01-01".to_string();
    }
    if y > 9_999 {
        return "9999-12-31".to_string();
    }
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        RunInfo {
            date: format_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
